class Entry:
 def __contains__(self,key): return key=="x"
 def __delitem__(self,key): self.deleted=key
class Manager(dict):
 def __enter__(self): return Entry()
 def __exit__(self,*args): pass
with Manager() as d:
 if "x" in d: del d["x"]
assert d.deleted=="x" and not hasattr(d,"pop")

import io
class Sink:
 def __init__(self): self.values=[]
 def write(self,value): self.values.append(value)
 def writelines(self,values): raise AssertionError("not equivalent")
class Manager(io.StringIO):
 def __enter__(self): return Sink()
with Manager() as fp:
 for line in ["a","b"]:
  fp.write(line)
assert fp.values==["a","b"] and not isinstance(fp,io.IOBase)

import io
class Source:
 def readlines(self): return ["a"]
 def __iter__(self): raise AssertionError("not equivalent")
class Manager(io.StringIO):
 def __enter__(self): return Source()
seen=[]
with Manager() as fp:
 for line in fp.readlines():
  seen.append(line)
assert seen==["a"] and not isinstance(fp,io.IOBase)
